// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        amount = bound(amount, 1, 1e30);

        // fund the contract so its low-level outgoing call succeeds
        vm.deal(address(c), amount);

        c.sendMoney(target, amount);

        // General rule: sendMoney never modifies the deposits counter.
        assertTrue(c.depositsCount() == 0);
    }
}
